/** @override */
goog.crypt.Hmac.prototype.reset = function() {
  'use strict';
  this.hasher_.reset();
  this.hasher_.update(this.keyI_);
};


/** @override */
goog.crypt.Hmac.prototype.update = function(bytes, opt_length) {
  'use strict';
  this.hasher_.update(bytes, opt_length);
};


