  var argument = AI.Yail.valueToCode(this, 'NUM', AI.Yail.ORDER_NONE) || 0;
  var code = AI.Yail.YAIL_CALL_YAIL_PRIMITIVE + "random-set-seed"
      + AI.Yail.YAIL_SPACER;
